    &lt;span class="c"&gt;// Calculate averages&lt;/span&gt;
    &lt;span class="n"&gt;totalComp&lt;/span&gt; &lt;span class="o"&gt;:=&lt;/span&gt; &lt;span class="m"&gt;0.0&lt;/span&gt;
