        &lt;span class="n"&gt;AvgTotalComp&lt;/span&gt;&lt;span class="o"&gt;:&lt;/span&gt;      &lt;span class="n"&gt;avgComp&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt;
        &lt;span class="n"&gt;AvgReplacementCost&lt;/span&gt;&lt;span class="o"&gt;:&lt;/span&gt; &lt;span class="n"&gt;avgReplacement&lt;/span&gt;&lt;span class="p"&gt;,&lt;/span&gt;
